import React from 'react';
import { NavLink } from 'react-router-dom';
import { 
  BiSpeedometer2, 
  BiBox, 
  BiCart3, 
  BiClipboardCheck, 
  BiCart, 
  BiPeople, 
  BiGraphUp, 
  BiTag, 
  BiPerson, 
  BiGear 
} from 'react-icons/bi';

const Sidebar = () => {
  const navItems = [
    { path: '/', icon: BiSpeedometer2, label: 'Dashboard' },
    { path: '/products', icon: BiBox, label: 'Products' },
    { path: '/cart', icon: BiCart3, label: 'Cart' },
    { path: '/inventory', icon: BiClipboardCheck, label: 'Inventory' },
    { path: '/orders', icon: BiCart, label: 'Orders' },
    { path: '/customers', icon: BiPeople, label: 'Customers' },
    { path: '/reports', icon: BiGraphUp, label: 'Reports' },
    { path: '/promotions', icon: BiTag, label: 'Promotions' },
    { path: '/users', icon: BiPerson, label: 'Users' },
    { path: '/settings', icon: BiGear, label: 'Settings' },
  ];

  return (
    <nav className="sidebar">
      <div className="position-sticky pt-3">
        <div className="text-center mb-4">
          <h2>My Bakery</h2>
        </div>
        <ul className="nav flex-column">
          {navItems.map((item) => (
            <li key={item.path} className="nav-item">
              <NavLink
                to={item.path}
                className={({ isActive }) => 
                  `nav-link ${isActive ? 'active' : ''}`
                }
              >
                <item.icon className="me-2" />
                {item.label}
              </NavLink>
            </li>
          ))}
        </ul>
      </div>
    </nav>
  );
};

export default Sidebar;
